/* a logo into context x, centred at (cx, cy) and fitted in a square of half size r, filled col; edge: a colour for an
   outline ew wide (in the context's own units), or nothing. False where the logo or Path2D is missing. */
function logoDraw(x,id,cx,cy,r,col,edge,ew){const m=LOGOS[id];if(!m||typeof Path2D==="undefined")return false;
  if(!m.c)m.c=m.p.map(q=>[new Path2D(q[0]),q[1]?"evenodd":"nonzero"]);const k=2*r/Math.max(m.b[2],m.b[3]);
  x.save();x.translate(cx,cy);x.scale(k,k);x.translate(-(m.b[0]+m.b[2]/2),-(m.b[1]+m.b[3]/2));
  if(edge){x.strokeStyle=edge;x.lineWidth=(ew||0.05)/k;x.lineJoin="round";for(const q of m.c)x.stroke(q[0]);}
  x.fillStyle=col;for(const q of m.c)x.fill(q[0],q[1]);x.restore();return true;}
/* the same as an <svg> string px square, or "" where there is no such logo */
function logoSvg(id,col,px){const m=LOGOS[id];if(!m)return"";const s=Math.max(m.b[2],m.b[3]),x=m.b[0]+m.b[2]/2-s/2,y=m.b[1]+m.b[3]/2-s/2;
  return`<svg viewBox="${x} ${y} ${s} ${s}" width="${px}" height="${px}" aria-hidden="true" focusable="false"><g fill="${col}">${m.p.map(q=>`<path d="${q[0]}"${q[1]?' fill-rule="evenodd"':""}/>`).join("")}</g></svg>`;}
/* black or white, whichever shows better on colour hex ("#rrggbb"): a logo on a sponsor's own colour */
function logoInk(hex){const n=parseInt(String(hex).slice(1),16)||0,l=(0.299*(n>>16&255)+0.587*(n>>8&255)+0.114*(n&255))/255;return l>0.6?"#1B1B1E":"#FFFFFF";}
/* a logo as a decal material on a panel of colour bg. Full and Ultra: cut out on its alpha, lit like the paint. Lite: a
   solid tile of the panel's own colour with the logo on it, so a logo a dozen pixels across stays smooth (a cut-out
   breaks up that small) and nothing blends */
function logoMat(id,col,bg){if(!LOGOS[id]||typeof Path2D==="undefined")return null;const lite=V.tier==="lite",k="logo|"+id+"|"+col+"|"+(lite?bg:"");let m=V.badgeMats[k];if(m)return m;
  const px=128,c=document.createElement("canvas");c.width=c.height=px;const x=c.getContext("2d");if(lite){x.fillStyle=bg;x.fillRect(0,0,px,px);}logoDraw(x,id,px/2,px/2,px*0.46,col);
  const t=new THREE.CanvasTexture(c);t.encoding=THREE.sRGBEncoding;t.anisotropy=lite?1:4;
  m=V.badgeMats[k]=lite?new THREE.MeshLambertMaterial({map:t}):new THREE.MeshStandardMaterial({map:t,alphaTest:0.5,roughness:0.45,metalness:0});return m;}
